assertions.text:
// WaveRoot candidate assertion a1. Not validated: it restates one
// trace observation and the golden expected value. Review before relying on it.
// Failure: TOP.tb.dut.full expected 1'b1, observed 1'b0 at 55000 ps
//   (epoch 0, cycle 3, settled).
// Top suspect: TOP.tb.dut.wptr (rtl/mutant/fifo.sv:38).
// Cause terms (operands the suspect consumed): wptr, push.
// Context terms (remaining pre-edge state of the sink): pop, rptr.
module waveroot_chk_a1 (
  input logic clk,
  input logic rst_n,
  input logic [2:0] wptr,
  input logic push,
  input logic pop,
  input logic [2:0] rptr,
  input logic full
);
  property p_waveroot_a1;
    @(posedge clk) disable iff (rst_n !== 1'b1)
    ((wptr === 3'b011) && (push === 1'b1) && (pop === 1'b0) && (rptr === 3'b000))
    |=> (!$isunknown(full) && (full == 1'b1));
  endproperty
  a_waveroot_a1: assert property (p_waveroot_a1);
  c_waveroot_a1: cover property (@(posedge clk) disable iff (rst_n !== 1'b1) ((wptr === 3'b011) && (push === 1'b1) && (pop === 1'b0) && (rptr === 3'b000)));
endmodule
bind fifo waveroot_chk_a1 u_waveroot_chk_a1 (.clk(clk), .rst_n(rst_n), .wptr(wptr), .push(push), .pop(pop), .rptr(rptr), .full(full));
